    fn new(base: &'a OllamaNative) -> Self {
        Self {
            base,
            base_url: None,
            env_auth: None,
            auth_update: schematic_define::UpdateStrategy::NoChange,
            headers: None,
            pre_response_json: None,
            response_mutators: std::collections::HashMap::new(),
        }
    }
    /// Sets the base URL for the variant.
